def set_colors_and_order(apps, schema_editor):
    Terminology = apps.get_model("core", "Terminology")
    field_paths = set(Terminology.objects.values_list("field_path", flat=True))
    for field_path in field_paths:
        names = SEED_ORDER.get(field_path, [])
        rows = Terminology.objects.filter(field_path=field_path)
        seeded = {t.name: t for t in rows.filter(builtin=True, name__in=names)}
        for position, name in enumerate(names, start=1):
            row = seeded.get(name)
            if row is None:
                continue
            row.order = position
            row.hexcolor = seed_hexcolor(field_path, name)
            row.save(update_fields=["order", "hexcolor"])
        # Customer values follow the built-ins, alphabetically.
        position = len(names)
        rest = rows.exclude(pk__in=[t.pk for t in seeded.values()]).order_by("name")
        for row in rest:
            position += 1
            row.order = position
            row.save(update_fields=["order"])


